insert into public.training_modules (course_id,title,summary,position)
values ((select id from public.training_courses where slug='australian-va-fundamentals'),'Working With Australian Businesses','Learn the operating context before specializing.',1)
on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-va-fundamentals') and position=1),
  'how-australian-small-businesses-work-with-vas','How Australian Small Businesses Work With VAs','Australian clients range from solo operators and trades businesses to clinics, agencies, property firms, e-commerce stores, and professional services. The software and industry may change, but good VA support begins with understanding who makes decisions, how work is documented, and what the client expects you to own.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize common Australian SME working patterns","Understand what clients usually expect from offshore support","Separate administrative ownership from professional or regulated decisions"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Australian clients range from solo operators and trades businesses to clinics, agencies, property firms, e-commerce stores, and professional services. The software and industry may change, but good VA support begins with understanding who makes decisions, how work is documented, and what the client expects you to own."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Australian businesses may use a mix of cloud software, email, phone, SMS, accounting systems, job-management tools, and spreadsheets.","A VA may be trusted with recurring workflows, but authority must be documented rather than assumed.","Small teams often expect concise updates and independent follow-through, not constant permission-seeking for routine work.","Country context adds local terminology and timing; it does not make the VA a lawyer, accountant, tax agent, health professional, or licensed industry adviser."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Map the business type, customers, team roles, and decision owners.","Identify the source-of-truth systems for contacts, tasks, documents, scheduling, and billing.","List routine actions you can complete independently.","List actions that require client approval or a qualified professional.","Agree on update cadence, escalation channels, and response-time expectations.","Write the workflow down so another person can continue it."]},{"type":"callout","title":"Stay inside the role","text":"Do not treat familiarity with Australian terminology as authority to give regulated advice. Industry-specific legal, tax, health, credit, tenancy, employment, or compliance decisions remain with the appropriate authorized person."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Assuming all Australian businesses work the same way","Using local slang to sound Australian instead of communicating clearly","Waiting for approval on every routine task even when the SOP already gives authority","Making high-impact decisions because the client is offline","Keeping critical context only in private notes"]},{"type":"scenario","title":"Practice scenario","text":"You support a six-person Australian service business. The owner says, ''Please take care of admin while I''m on jobs.'' Write the questions you need answered before you can safely own inbox triage, customer bookings, quote follow-up, invoice reminders, and supplier coordination."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Understand the business before optimizing it.","Own routine work within clear limits.","Keep decisions, exceptions, and next actions visible.","Country context supports judgment; it does not replace professional qualifications."]}]'::jsonb,
  23,1,false,1,null,null,now(),now()
)
