insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-va-fundamentals') and position=1),
  'australian-business-language-dates-and-communication','Australian Business Language, Dates, and Communication','Small differences in date format, spelling, phone numbers, state abbreviations, and business terminology can create avoidable friction. The goal is not to imitate an accent or slang. It is to make communication feel natural, accurate, and easy to act on.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Use common Australian business conventions accurately","Write concise client and customer messages without sounding artificial","Avoid date, spelling, address, and terminology errors"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Small differences in date format, spelling, phone numbers, state abbreviations, and business terminology can create avoidable friction. The goal is not to imitate an accent or slang. It is to make communication feel natural, accurate, and easy to act on."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Australian dates commonly use day/month/year in business contexts.","Australian English spelling often differs from US spelling, for example organise, centre, licence as a noun in some contexts, and programme in limited uses.","States and territories have standard abbreviations such as NSW, VIC, QLD, SA, WA, TAS, NT, and ACT.","ABN means Australian Business Number; GST means Goods and Services Tax; BAS means Business Activity Statement. Understanding the terms does not authorize you to advise on them.","Clear, direct communication is usually better than long greetings, exaggerated politeness, or filler."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Use the client''s existing style guide and templates first.","Confirm how dates should appear in customer-facing material.","Store phone numbers and addresses in the client''s chosen format.","Use plain language and put the action or decision near the top of the message.","When a term has legal, tax, employment, or regulatory meaning, use approved wording rather than paraphrasing it casually."]},{"type":"callout","title":"Stay inside the role","text":"Do not ''Australianise'' formal legal, tax, policy, medical, or contractual wording. Use the client''s approved version and escalate if meaning is unclear."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Writing 03/04/2026 without checking whether the reader may interpret it differently","Using US terminology copied from generic templates","Adding ''mate'' or slang to sound local","Changing formal wording because it sounds awkward","Sending long messages that bury the requested action"]},{"type":"scenario","title":"Practice scenario","text":"An Australian client asks you to send a meeting confirmation for 4/10/2026 and a quote follow-up using an old US template. Explain what you would verify before sending either message."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Accuracy matters more than sounding local.","Use client-approved terminology.","Make dates and actions unambiguous.","Keep formal wording intact unless authorized to edit it."]}]'::jsonb,
  23,2,false,1,null,null,now(),now()
)
