insert into public.training_modules (course_id,title,summary,position)
values ((select id from public.training_courses where slug='australian-va-fundamentals'),'Time, Privacy, and Access','Handle distributed work and sensitive information safely.',2)
on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-va-fundamentals') and position=2),
  'australian-time-zones-daylight-saving-and-scheduling','Australian Time Zones, Daylight Saving, and Scheduling','Australia spans multiple time zones, and daylight saving does not apply uniformly. Memorized offsets can become wrong. A reliable VA works from the actual location and date rather than assuming ''Australia time''.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Coordinate Manila and Australian schedules safely","Recognize why one Australian time zone is not enough","Build calendar habits that survive daylight-saving changes"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Australia spans multiple time zones, and daylight saving does not apply uniformly. Memorized offsets can become wrong. A reliable VA works from the actual location and date rather than assuming ''Australia time''."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Sydney and Melbourne may use daylight saving while Brisbane does not.","Perth operates on a different western time zone.","Adelaide uses a half-hour offset from some eastern zones.","Daylight-saving transitions can change the offset between Manila and an Australian client.","Meeting invitations should carry an actual time zone, not only a typed local time in the description."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Store the client''s city and business time zone, not just ''Australia''.","Check the attendee''s location for external meetings.","Use calendar time-zone conversion for the specific date.","Apply client rules for buffers, travel, lunch, and protected focus time.","Repeat critical deadlines with date, time, and time zone when ambiguity is possible.","Recheck recurring meetings across daylight-saving transitions."]},{"type":"callout","title":"Stay inside the role","text":"If a legal, payroll, tender, settlement, medical, or compliance deadline depends on local time, confirm the authoritative deadline with the responsible person instead of relying on your own conversion."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Using Sydney time for a Brisbane client during daylight saving","Assuming Perth is only one hour behind eastern Australia","Typing a converted time manually but creating the calendar event in the wrong zone","Ignoring daylight-saving changes on recurring meetings","Using ''tomorrow morning'' in cross-border handoffs"]},{"type":"scenario","title":"Practice scenario","text":"A Sydney client, a Brisbane supplier, and a Manila VA need a recurring 10:00 AM Sydney meeting from September through December. Describe how you would create and verify the recurrence so Brisbane and Manila participants do not receive the wrong expectation after daylight-saving changes."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use city plus time zone.","Convert using the actual date.","Let calendar systems handle recurrence where possible.","Write critical cross-border deadlines explicitly."]}]'::jsonb,
  23,1,false,1,null,null,now(),now()
)
on conflict (module_id,slug) do update set
