insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-va-fundamentals') and position=2),
  'australian-privacy-personal-information-and-offshore-va-access','Australian Privacy, Personal Information, and Offshore VA Access','Australian businesses may be subject to the Privacy Act and Australian Privacy Principles, and health information receives additional protection. Even where a particular organization has different legal coverage, treating personal information carefully is a basic professional standard.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize personal and sensitive information","Apply minimum-necessary access in a remote VA workflow","Understand why cross-border handling needs client-approved controls"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Australian businesses may be subject to the Privacy Act and Australian Privacy Principles, and health information receives additional protection. Even where a particular organization has different legal coverage, treating personal information carefully is a basic professional standard."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Personal information can include names, contact details, financial information, identifiers, employment data, and other information about an identifiable person.","Health information is especially sensitive.","The Australian Privacy Principles cover areas including collection, use/disclosure, data quality, security, access, and correction.","Offshore VAs should use only approved systems, accounts, and sharing methods.","Privacy obligations depend on the organization and context; a VA should follow the client''s privacy and security controls rather than make legal interpretations."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Identify what personal information the task actually requires.","Use the client''s approved account and permission level.","Avoid copying data into personal email, personal cloud storage, screenshots, or unapproved AI tools.","Share information only with the intended authorized recipient.","Lock down files and links to the minimum access required.","Report accidental exposure, wrong-recipient sends, or suspicious access immediately under the client''s incident process."]},{"type":"callout","title":"Stay inside the role","text":"This course teaches safe administrative handling, not legal advice about whether a specific business is covered by the Privacy Act or how a particular APP applies. Those questions belong with the client''s privacy, legal, or compliance owner."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Downloading entire customer lists when only five records are needed","Pasting patient or financial data into an AI tool without approval","Using public share links for convenience","Leaving sensitive downloads on a personal device","Trying to quietly fix a privacy incident without reporting it"]},{"type":"scenario","title":"Practice scenario","text":"You are asked to summarize 40 customer complaints. The spreadsheet contains addresses, mobile numbers, payment references, and medical details unrelated to the complaints. Explain how you would minimize the information you use and where you would do the work."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use minimum necessary data.","Keep work in approved systems.","Treat health and financial data as high sensitivity.","Escalate incidents rather than hiding them."]}]'::jsonb,
  23,2,false,1,null,null,now(),now()
)
