insert into public.training_modules (course_id,title,summary,position)
values ((select id from public.training_courses where slug='australian-va-fundamentals'),'Australian Business Administration','Understand common administrative concepts without crossing into professional advice.',3)
on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-va-fundamentals') and position=3),
  'abn-gst-bas-invoices-and-finance-terminology-for-vas','ABN, GST, BAS, Invoices, and Finance Terminology for VAs','Australian VAs regularly see ABNs, GST, tax invoices, BAS, payroll, super, and ATO references. You need enough context to route and organize the work correctly without pretending to be qualified to determine tax treatment.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Recognize common Australian finance-admin terms","Understand where a VA can support document workflows","Know when a question belongs to a bookkeeper, accountant, BAS agent, or client"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Australian VAs regularly see ABNs, GST, tax invoices, BAS, payroll, super, and ATO references. You need enough context to route and organize the work correctly without pretending to be qualified to determine tax treatment."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["An ABN identifies an Australian business in many business dealings.","GST and BAS are common parts of Australian business administration.","Invoices, bills, receipts, credit notes, and statements serve different record-keeping purposes.","Payroll and Single Touch Payroll have specific Australian compliance workflows.","The correct tax code, BAS treatment, payroll treatment, or statutory obligation may require an authorized bookkeeper, BAS agent, accountant, payroll specialist, or client decision."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Identify the document type and business/entity it belongs to.","Capture the fields the client''s workflow requires.","Check for obvious missing information or duplicates.","Attach the source document to the approved system.","Route coding, GST, payroll, or statutory questions to the designated reviewer.","Track the item until approval, payment, or handoff is confirmed."]},{"type":"callout","title":"Stay inside the role","text":"A VA may prepare and organize finance records, but should not decide GST treatment, lodge BAS, declare STP, calculate statutory obligations, or give tax/accounting advice unless specifically qualified and authorized."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Assuming every invoice includes GST","Changing a tax code because another transaction looks similar","Treating BAS as a generic monthly report","Submitting payroll or tax declarations using someone else''s authority","Deleting source documents after data entry"]},{"type":"scenario","title":"Practice scenario","text":"A supplier invoice has an ABN and total amount but the GST treatment does not match similar invoices. Describe the administrative steps you can take and the decision you should not make."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Learn the vocabulary so you can route work correctly.","Preserve source documents.","Use approved coding rules only.","Escalate tax and statutory judgment."]}]'::jsonb,
  23,1,false,1,null,null,now(),now()
)
on conflict (module_id,slug) do update set
  title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=excluded.estimated_minutes,
