insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-va-fundamentals') and position=3),
  'australian-customer-service-and-administrative-follow-up','Australian Customer Service and Administrative Follow-Up','Many Australian SME roles blend administration and customer service. The VA may confirm bookings, chase approved quotes, request missing documents, update customers, or follow up invoices. Consistency and evidence matter more than sounding salesy.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Write clear routine updates for Australian customers","Build follow-up systems that do not depend on memory","Escalate complaints, payments, and sensitive matters appropriately"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Many Australian SME roles blend administration and customer service. The VA may confirm bookings, chase approved quotes, request missing documents, update customers, or follow up invoices. Consistency and evidence matter more than sounding salesy."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["The customer should know the confirmed status, action taken, and next step.","A follow-up task needs an owner and date.","Templates save time but should be adjusted when the situation changed.","Complaints, threats, legal issues, payment disputes, safety concerns, and regulatory matters need defined escalation.","Do not promise arrival times, refunds, outcomes, or approvals the business has not confirmed."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the full customer history before replying.","Use the approved template or tone.","State the confirmed status first.","Ask only for the missing information needed to progress the task.","Create the next task or reminder immediately.","Record the interaction in the source system.","Escalate exceptions with context and a clear decision request."]},{"type":"callout","title":"Stay inside the role","text":"Customer service authority varies by business. Never assume you can approve refunds, discounts, write-offs, contract changes, payment plans, or complaint outcomes just because you can draft the message."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Sending a generic follow-up after the customer already replied","Promising ''today'' without confirmed capacity","Using artificial empathy such as ''I completely understand your frustration'' when you do not know the full context","Failing to log phone or SMS interactions","Leaving the next action only in your inbox"]},{"type":"scenario","title":"Practice scenario","text":"A customer says, ''I''ve already called twice and nobody came.'' The job system shows one cancelled booking and no new appointment. Draft the structure of a useful reply and identify what needs internal escalation."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Read history before messaging.","Lead with confirmed facts.","Create visible next actions.","Escalate decisions, not routine administration."]}]'::jsonb,
  23,2,false,1,null,null,now(),now()
)
