insert into public.training_modules (course_id,title,summary,position)
values ((select id from public.training_courses where slug='australian-va-fundamentals'),'Remote Operations and Simulation','Work independently across borders without losing context.',4)
on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-va-fundamentals') and position=4),
  'daily-handoffs-between-the-philippines-and-australia','Daily Handoffs Between the Philippines and Australia','A Philippines-based VA may finish work while an Australian client is still active, or begin before part of the team comes online. A disciplined handoff turns the time difference into useful coverage instead of confusion.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Create handoffs that exploit time-zone overlap and coverage","Separate routine status from decisions","Prevent work from disappearing between shifts"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"A Philippines-based VA may finish work while an Australian client is still active, or begin before part of the team comes online. A disciplined handoff turns the time difference into useful coverage instead of confusion."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["A handoff is a transfer of ownership, not a diary.","Exceptions, deadlines, and decisions deserve more visibility than routine completed work.","Links to tasks and source records reduce reconstruction time.","The next person should know what to do without asking what happened.","Recurring handoff formats make omissions easier to spot."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["List completed outcomes briefly.","List blocked or waiting items with the blocking party.","List decisions needed with enough context to answer them.","Call out deadlines in Australian local time.","Identify customer or operational risk.","Assign the next owner and next checkpoint.","Queue tomorrow''s first actions before signing off."]},{"type":"callout","title":"Stay inside the role","text":"Do not keep working outside agreed hours merely because a client is still online. Coverage, overtime, availability, and emergency expectations should be explicit."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Writing a chronological diary instead of a decision-focused handoff","Saying ''waiting on client'' without naming the item or deadline","Using Manila time without labeling it","Leaving urgent customer messages unassigned","Sending the same report every day even when it no longer helps"]},{"type":"scenario","title":"Practice scenario","text":"At 4:30 PM Manila time you have one customer waiting on an Australian manager''s approval, one supplier who promised a callback, two routine completed tasks, and a booking due to be confirmed by 3 PM Sydney time. Build the handoff order and explain why."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Put exceptions first.","Use links and owners.","Write deadlines in the recipient''s local context.","Finish with tomorrow''s first actions."]}]'::jsonb,
  23,1,false,1,null,null,now(),now()
)
on conflict (module_id,slug) do update set
  title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=excluded.estimated_minutes,
  position=excluded.position,is_published=false,reviewed_by=null,last_reviewed_at=null,
