insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-va-fundamentals') and position=4),
  'australian-va-composite-work-simulation','Australian VA Composite Work Simulation','The purpose of this simulation is to test judgment, not trivia. A strong VA should be able to move routine work forward, recognize Australian context, and stop at decisions that need the client or a qualified specialist.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Apply Australian context across a mixed admin day","Prioritize time-zone, privacy, finance, and customer-service issues","Show clear administrative boundaries"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"The purpose of this simulation is to test judgment, not trivia. A strong VA should be able to move routine work forward, recognize Australian context, and stop at decisions that need the client or a qualified specialist."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Business context","Time zones","Privacy","Finance terminology","Customer communication","Handoffs and escalation"]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the full fictional work queue before acting.","Rank items by consequence of delay, not message order.","Identify the source system and owner for each item.","Complete the routine administrative steps.","Write the escalation for restricted or uncertain decisions.","Prepare an end-of-day Australian-client handoff."]},{"type":"callout","title":"Stay inside the role","text":"Do not resolve tax treatment, legal obligations, privacy-law interpretation, payroll declarations, or refund/contract decisions in the simulation. Show that you know where the boundary is."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Treating every message as equally urgent","Using an Australian term confidently but incorrectly","Copying unnecessary personal data into working notes","Forgetting daylight-saving context","Closing tasks with no evidence or next action"]},{"type":"scenario","title":"Practice scenario","text":"You support a fictional Melbourne consultancy. The inbox contains a supplier invoice with unclear GST treatment, a customer asking for a refund, an appointment request from Perth, a spreadsheet containing unnecessary sensitive data, an overdue document request, and a manager asking for an end-of-day update. Produce the priority order, safe actions, escalation notes, and handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use Australian context without overclaiming expertise.","Protect customer data.","Make deadlines explicit.","Keep regulated decisions with authorized people."]}]'::jsonb,
  23,2,false,1,null,null,now(),now()
)
