insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-trades-administration') and position=1),
  'from-customer-enquiry-to-completed-job','From Customer Enquiry to Completed Job','Australian trade businesses such as plumbing, electrical, HVAC, cleaning, pest control, appliance repair, and maintenance often run around jobs rather than long projects. The VA helps preserve customer details, job scope, timing, evidence, and status from first contact through payment.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Map a typical trades job lifecycle","Recognize the VA''s administrative role at each stage","Understand where technician, estimator, owner, or licensed-trade judgment begins"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Australian trade businesses such as plumbing, electrical, HVAC, cleaning, pest control, appliance repair, and maintenance often run around jobs rather than long projects. The VA helps preserve customer details, job scope, timing, evidence, and status from first contact through payment."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["A job may move through enquiry, triage, booking, quote, approval, scheduling, field work, completion, invoice, payment, and follow-up.","Emergency and same-day workflows require business-defined rules.","A customer description is not the same as a technical diagnosis.","Technicians need clear scope and access information before arriving.","Job history is valuable for future warranty, repeat-service, and customer communication."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Capture the customer''s request accurately.","Identify the approved urgency category or escalate if unclear.","Create the job in the source system.","Attach photos, messages, asset details, or previous job history.","Schedule or route the job according to dispatch rules.","Track quote or approval if required.","Record completion evidence and follow-up items.","Move invoice/payment administration through the approved process."]},{"type":"callout","title":"Stay inside the role","text":"A VA should not diagnose electrical, plumbing, gas, HVAC, structural, or other technical faults, nor promise safety or compliance outcomes. Record the customer''s description and route technical decisions to qualified staff."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Turning the customer''s guess into the job diagnosis","Booking work without access details","Creating a new customer when a duplicate already exists","Marking a job complete because the calendar event ended","Failing to record follow-up or warranty issues"]},{"type":"scenario","title":"Practice scenario","text":"A customer says, ''The breaker keeps tripping and I think the switchboard is broken.'' Write the job description you would record without adopting the customer''s diagnosis as fact."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Capture symptoms and context, not technical conclusions.","Keep job status evidence-based.","Make the next owner clear.","Preserve job history."]}]'::jsonb,
  30,1,false,1,null,null,now(),now()
)
on conflict (module_id,slug) do update set
