insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-trades-administration') and position=1),
  'emergency-urgent-and-routine-job-triage','Emergency, Urgent, and Routine Job Triage','Trades businesses receive everything from routine maintenance to possible safety emergencies. A remote VA needs a clear triage process because delay can worsen risk, but overreacting can also disrupt schedules and costs.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Use client-defined triage rules","Recognize when safety or property risk needs immediate escalation","Avoid making technical or legal determinations"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Trades businesses receive everything from routine maintenance to possible safety emergencies. A remote VA needs a clear triage process because delay can worsen risk, but overreacting can also disrupt schedules and costs."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Urgency should be defined by the business, not the VA''s intuition alone.","Potential gas, electrical, fire, flooding, security, or serious property-damage issues usually need a fast escalation path.","The VA can collect information but should not give technical safety instructions beyond approved scripts.","Availability, location, travel, parts, and qualified personnel affect dispatch.","After-hours and emergency pricing or authority should be documented."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Use the business''s emergency checklist.","Collect location, contact, symptoms, when the issue started, and immediate risk indicators.","Tell the customer only approved safety or emergency information.","Escalate to the designated technician/manager if the category is unclear or high risk.","Record the decision and dispatch owner.","Update the customer with confirmed timing only."]},{"type":"callout","title":"Stay inside the role","text":"Do not tell a customer an electrical, gas, plumbing, fire, or structural situation is safe. If the client''s emergency instructions include contacting emergency services or an authority, follow that script exactly."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Using ''urgent'' for every unhappy customer","Downplaying a possible safety issue because the schedule is full","Promising a technician arrival time before dispatch confirms it","Giving DIY technical advice","Failing to preserve the original customer description"]},{"type":"scenario","title":"Practice scenario","text":"A caller reports a burning smell near an electrical outlet and asks whether they can keep using it until tomorrow. Explain the VA''s administrative response without giving technical safety advice beyond the company''s approved emergency script."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use a written triage rule.","Escalate uncertainty in high-risk cases.","Do not diagnose.","Communicate only confirmed dispatch information."]}]'::jsonb,
  30,2,false,1,null,null,now(),now()
)
