insert into public.training_modules (course_id,title,summary,position)
values ((select id from public.training_courses where slug='australian-trades-administration'),'Scheduling, Quotes, and Field Coordination','Keep the office and field aligned.',2)
on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-trades-administration') and position=2),
  'scheduling-technicians-travel-and-job-windows','Scheduling Technicians, Travel, and Job Windows','A calendar can look available while the field schedule is impossible. Trades scheduling must consider location, technician skills, travel, existing jobs, emergency capacity, parts, property access, and customer windows.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Build realistic trade schedules","Account for travel, job duration, skills, and access","Handle schedule changes without losing customer context"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"A calendar can look available while the field schedule is impossible. Trades scheduling must consider location, technician skills, travel, existing jobs, emergency capacity, parts, property access, and customer windows."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Job duration is often estimated and may change in the field.","The nearest technician may not have the required licence, skill, equipment, or part.","Buffers protect against travel and overruns.","Customer appointment windows must reflect business policy.","Schedule changes should update both staff and customer-facing records."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm job type and required skill or technician constraints.","Check location and travel between jobs.","Use the business''s duration and buffer rules.","Check access restrictions and customer availability.","Schedule in the source system.","Confirm the booking using approved wording.","If the schedule changes, update technician, customer, and job record together."]},{"type":"callout","title":"Stay inside the role","text":"Do not assign regulated work to someone merely because they are available. Follow the client''s technician/qualification rules."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Back-to-back bookings across distant suburbs","Ignoring required parts or equipment","Moving jobs without telling the customer","Booking a technician outside the job type they are approved for","Using calendar availability as the only scheduling signal"]},{"type":"scenario","title":"Practice scenario","text":"A technician finishes in Parramatta at 1 PM. A new 1:30 PM job appears in Manly and is estimated at two hours. Explain the checks you would make before confirming it."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Schedule the field, not just the calendar.","Use skill and travel constraints.","Update all affected parties.","Keep schedule evidence in the job system."]}]'::jsonb,
  30,1,false,1,null,null,now(),now()
)
on conflict (module_id,slug) do update set
