insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-trades-administration') and position=2),
  'quote-administration-and-follow-up','Quote Administration and Follow-Up','Quote workflows often involve site notes, labour, materials, photos, templates, pricing approval, sending, questions, acceptance, and scheduling. The VA can coordinate the workflow while leaving technical scope and price decisions with authorized staff.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Support quoting without inventing price or scope","Track quote status and customer questions","Create useful follow-up without pressure or false promises"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Quote workflows often involve site notes, labour, materials, photos, templates, pricing approval, sending, questions, acceptance, and scheduling. The VA can coordinate the workflow while leaving technical scope and price decisions with authorized staff."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Drafting from an approved price book is different from deciding the price.","Quote versions matter.","Customer acceptance should be recorded from evidence.","Changes in scope may require a revised quote.","Follow-up should reflect the customer''s actual history."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm the estimate/quote inputs are complete.","Use the approved template or system.","Route technical scope or price questions to the estimator/owner.","Check customer details, validity period, exclusions, and attachments.","Send only after approval if required.","Track sent, viewed, questioned, accepted, declined, or expired status.","Create a follow-up task based on business cadence."]},{"type":"callout","title":"Stay inside the role","text":"Do not change labour rates, margins, materials, exclusions, warranty promises, or technical scope without authority."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Editing price to ''help win the job''","Sending an old quote version","Following up after the customer already declined","Treating a verbal question as acceptance","Booking work before the required acceptance or deposit step"]},{"type":"scenario","title":"Practice scenario","text":"A customer replies, ''Can you do it for $500 less if we pay today?'' Draft the admin response and escalation without negotiating on the business''s behalf."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Preserve quote versions.","Separate admin from pricing judgment.","Record customer status accurately.","Follow up from context, not automation alone."]}]'::jsonb,
  30,2,false,1,null,null,now(),now()
)
