insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-trades-administration') and position=3),
  'customer-updates-delays-and-job-completion','Customer Updates, Delays, and Job Completion','Customers judge a trade business not only by technical work but by communication. A VA often becomes the continuity point when technicians are on site and owners are busy.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Give useful status updates","Handle delays without overpromising","Close jobs only from evidence"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Customers judge a trade business not only by technical work but by communication. A VA often becomes the continuity point when technicians are on site and owners are busy."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["A useful update includes confirmed status, action, and next step.","Technician notes, photos, signatures, forms, or completion status may be required evidence.","A job can be physically complete but administratively open.","Return visits, parts orders, and warranty checks need visible next actions.","Complaints should be routed before they become hidden inbox problems."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the latest field notes before messaging.","Confirm whether the job is complete, paused, awaiting parts, or needs a return visit.","Send the approved customer update.","Create follow-up tasks for outstanding work.","Collect required completion evidence.","Move the job to invoicing only when the client''s criteria are satisfied."]},{"type":"callout","title":"Stay inside the role","text":"Do not promise that work is compliant, safe, warrantable, or permanently fixed unless the authorized technician/business has confirmed that wording."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Saying ''all fixed'' because a technician left site","Hiding delays until the customer asks","Closing a job with missing photos or forms","Forgetting a return visit","Giving a technical explanation not present in the field notes"]},{"type":"scenario","title":"Practice scenario","text":"The technician note says ''temporary repair, part ordered, return required.'' Write the status you would record and the customer update you would send."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Read field notes.","Use evidence-based status.","Track return work.","Avoid technical overclaims."]}]'::jsonb,
  30,1,false,1,null,null,now(),now()
)
on conflict (module_id,slug) do update set
  title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=excluded.estimated_minutes,
