insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-trades-administration') and position=3),
  'supplier-parts-and-purchase-administration','Supplier, Parts, and Purchase Administration','A field-service job may be blocked by parts, supplier availability, purchase approvals, lead times, or delivery. Good supplier administration prevents a customer job from disappearing while everyone waits.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Track parts and supplier dependencies","Keep purchase evidence organized","Escalate cost or substitution decisions"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"A field-service job may be blocked by parts, supplier availability, purchase approvals, lead times, or delivery. Good supplier administration prevents a customer job from disappearing while everyone waits."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Part numbers and descriptions should come from approved technical input.","Supplier quote and purchase approval are different stages.","Lead time affects scheduling.","Substitutions may change compatibility, price, or compliance.","Receipts and supplier invoices need to connect back to the job."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Record the requested item exactly from technician/approved source.","Request or record supplier availability and price if authorized.","Route approval according to spending limits.","Place the order only within delegated authority.","Record expected delivery or pickup.","Update the blocked job and customer timing if approved.","Attach invoice/receipt to the correct job or finance record."]},{"type":"callout","title":"Stay inside the role","text":"Do not select substitute technical parts or approve purchases above your delegated limit."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Guessing a part from a customer description","Ordering before approval","Failing to link the purchase to the job","Promising job timing before supplier confirmation","Accepting a substitute without technician approval"]},{"type":"scenario","title":"Practice scenario","text":"A supplier says the requested part is unavailable but offers a cheaper alternative. Describe the information you record and who must decide whether the alternative is acceptable."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Track dependencies explicitly.","Keep part decisions with qualified staff.","Respect spend authority.","Connect supplier records to jobs."]}]'::jsonb,
  30,2,false,1,null,null,now(),now()
)
