insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-trades-administration') and position=4),
  'invoicing-payment-follow-up-and-accounting-handoff','Invoicing, Payment Follow-Up, and Accounting Handoff','Trade businesses often lose cash flow when completed jobs are not invoiced promptly or invoices are missing the right job evidence. The VA can make the administrative path reliable without deciding tax treatment or financial policy.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Move completed jobs into clean invoice administration","Follow up approved outstanding invoices","Prepare accurate accounting handoffs"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"Trade businesses often lose cash flow when completed jobs are not invoiced promptly or invoices are missing the right job evidence. The VA can make the administrative path reliable without deciding tax treatment or financial policy."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Invoice content should reflect approved job, labour, materials, and price information.","GST treatment and accounting codes should follow the client''s approved accounting process.","Payments and outstanding balances should be recorded from evidence.","Payment reminders should follow business policy.","Accounting integrations still require exception review."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm the job meets invoicing criteria.","Check customer and billing details.","Use approved job items and price information.","Route GST/accounting questions to the designated finance reviewer.","Send the invoice through the approved channel.","Record payment or outstanding status from the system.","Follow up according to policy.","Prepare exceptions for bookkeeper/accountant review."]},{"type":"callout","title":"Stay inside the role","text":"Do not decide GST coding, write off debt, change payment terms, approve credits, or make accounting judgments unless authorized and qualified."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Creating an invoice before work is ready to bill","Changing tax codes because the software suggests one","Sending reminders to already-paid customers","Writing off an invoice to clean the dashboard","Failing to reconcile job status with accounting status"]},{"type":"scenario","title":"Practice scenario","text":"The job is marked complete, but a material item in the field notes is missing from the draft invoice and the GST treatment is unclear. Explain the admin steps and escalation."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Invoice from approved evidence.","Respect finance boundaries.","Check payment status before chasing.","Report exceptions."]}]'::jsonb,
  30,1,false,1,null,null,now(),now()
)
