insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='australian-trades-administration') and position=4),
  'australian-trades-composite-work-simulation','Australian Trades Composite Work Simulation','This simulation tests whether you can keep a trade business moving without becoming the technician, estimator, accountant, or owner.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Run a mixed trade-business admin day","Prioritize safety, customer, scheduling, supplier, and billing work","Produce a clean handoff"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"This simulation tests whether you can keep a trade business moving without becoming the technician, estimator, accountant, or owner."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Job triage","Scheduling","Quotes","Customer communication","Suppliers","Invoices","Handoffs"]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the fictional queue.","Identify urgent/safety escalations.","Create job records and next actions.","Resolve routine scheduling and customer updates.","Prepare quote, supplier, and invoice escalation notes.","Finish with an end-of-day handoff."]},{"type":"callout","title":"Stay inside the role","text":"Stay inside administrative authority. Do not diagnose faults, approve unsafe work, negotiate unauthorized prices, choose regulated technical solutions, or make tax/accounting decisions."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Prioritizing the loudest customer rather than consequence","Overbooking technicians","Changing scope to satisfy a customer","Losing supplier dependencies","Treating invoicing as automatic after a calendar event"]},{"type":"scenario","title":"Practice scenario","text":"A fictional plumbing/electrical service business has an urgent leak report, a possible electrical safety issue, two schedule conflicts, a quote negotiation request, a missing part, a completed job awaiting invoice, and an overdue customer balance. Build the work queue, admin actions, escalations, and handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Safety and evidence first.","Schedule realistically.","Track dependencies.","Keep technical, pricing, and finance decisions with the right owners."]}]'::jsonb,
  30,2,false,1,null,null,now(),now()
)
