insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='servicem8-for-virtual-assistants') and position=1),
  'servicem8-job-lifecycle-and-va-role','ServiceM8 Job Lifecycle and VA Role','ServiceM8 is built around jobs. Current official materials describe a workflow from the client''s first call through scheduling, quoting, completion, invoicing, and payment. A VA should understand that lifecycle before editing records.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Understand ServiceM8''s client-to-job-to-invoice flow","Recognize which parts a VA can support remotely","Keep software actions aligned with the business''s real process"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"ServiceM8 is built around jobs. Current official materials describe a workflow from the client''s first call through scheduling, quoting, completion, invoicing, and payment. A VA should understand that lifecycle before editing records."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Job cards connect client details, job requirements, notes, photos, communication, and history.","Scheduling allocates work to staff and can notify them of changes.","Quotes and invoices can be created and sent through the platform.","Client/job history supports repeat work and customer context.","Accounting integrations can sync parts of the finance workflow, but exceptions still need review."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Identify the client''s actual ServiceM8 workflow and permissions.","Confirm which job statuses and queues the business uses.","Learn how client records and job cards relate.","Map when a job is quoted, scheduled, completed, invoiced, and closed.","Document the VA''s authority for customer messages, scheduling, quote sending, invoices, and payment follow-up."]},{"type":"callout","title":"Stay inside the role","text":"Do not confuse software permission with business authority. Being able to edit a quote, mark a job complete, issue an invoice, or take a payment does not mean the client has authorized you to make the underlying decision."},{"type":"callout","title":"Keep this current","text":"ServiceM8 changes over time. Before publishing or reviewing this lesson, verify the current workflow against official ServiceM8 help documentation. The course teaches administrative workflow, not vendor certification."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Learning buttons without learning the business workflow","Using job status inconsistently","Creating duplicate clients","Treating software suggestions as approvals","Changing financial information because the interface allows it"]},{"type":"scenario","title":"Practice scenario","text":"A new VA account has broad ServiceM8 permissions. List the questions you should ask before using quote, invoice, payment, and scheduling functions."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Understand the job lifecycle first.","Use consistent statuses.","Permission is not authority.","Keep the system aligned with reality."]}]'::jsonb,
  26,1,false,1,null,null,now(),now()
)
