insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='servicem8-for-virtual-assistants') and position=1),
  'clients-job-cards-notes-and-history','Clients, Job Cards, Notes, and History','A ServiceM8 job card can become the operational record that office and field staff rely on. Bad data creates bad dispatch, wrong customer communication, and billing problems.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Create clean client/job records","Write useful job descriptions and notes","Use history without copying stale information"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"A ServiceM8 job card can become the operational record that office and field staff rely on. Bad data creates bad dispatch, wrong customer communication, and billing problems."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Client identity and contact details should be checked before creating duplicates.","Job descriptions should record the customer''s reported problem or approved scope, not an unverified technical diagnosis.","Notes should distinguish customer statements, office actions, and technician findings.","Photos and files need the correct job association.","Past job history is useful context but not proof that the current issue is identical."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Search for the existing client.","Confirm address/site and contact details.","Create the job using the business''s naming/category rules.","Record the request in factual language.","Attach relevant messages, photos, or documents.","Review prior job history for context.","Create the next action or schedule according to workflow."]},{"type":"callout","title":"Stay inside the role","text":"Do not copy a previous technical diagnosis into a new job simply because the symptoms sound similar."},{"type":"callout","title":"Keep this current","text":"ServiceM8 changes over time. Before publishing or reviewing this lesson, verify the current workflow against official ServiceM8 help documentation. The course teaches administrative workflow, not vendor certification."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Duplicate clients","Vague job descriptions like ''fix issue''","Mixing customer claims with technician findings","Uploading files to the wrong job","Deleting history because it looks old"]},{"type":"scenario","title":"Practice scenario","text":"A repeat customer reports ''the same hot-water issue as last year.'' The old job had a failed component. Write the new job description without assuming the component failed again."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Search first.","Record facts.","Use history as context.","Keep attachments tied to the correct job."]}]'::jsonb,
  26,2,false,1,null,null,now(),now()
)
