insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='servicem8-for-virtual-assistants') and position=2),
  'scheduling-jobs-and-using-the-dispatch-view','Scheduling Jobs and Using the Dispatch View','ServiceM8 supports scheduling from job cards and dashboard views. The VA''s value is not just entering a time; it is ensuring the right staff, duration, location, and customer expectations are aligned.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Schedule jobs with realistic constraints","Understand staff allocation and booking details","Update customers and staff when schedules change"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"ServiceM8 supports scheduling from job cards and dashboard views. The VA''s value is not just entering a time; it is ensuring the right staff, duration, location, and customer expectations are aligned."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Bookings include staff, duration, date, and time.","Dispatch decisions should reflect skills, location, travel, and business rules.","Changing a booking can affect staff and customer communication.","Urgent jobs need the business''s dispatch process.","The job card should hold the context the field worker needs."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm job type and required staff constraints.","Review existing schedule and travel.","Set the booking using approved duration.","Add access or job notes needed by the field team.","Confirm customer details and communication.","When changed, update the booking and affected people together.","Record any unresolved dispatch issue."]},{"type":"callout","title":"Stay inside the role","text":"ServiceM8 may suggest available booking times, but the business still owns technician suitability, emergency priority, and customer commitment decisions."},{"type":"callout","title":"Keep this current","text":"ServiceM8 changes over time. Before publishing or reviewing this lesson, verify the current workflow against official ServiceM8 help documentation. The course teaches administrative workflow, not vendor certification."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Selecting the first suggested time without checking travel","Assigning a staff member without required skill","Changing a booking but forgetting the customer","Leaving access instructions out of the job","Using the calendar as proof the customer agreed"]},{"type":"scenario","title":"Practice scenario","text":"The dashboard suggests a 2 PM slot, but the technician is booked across town until 1:45. Explain how you would validate the suggestion before confirming it."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Treat suggestions as inputs, not decisions.","Check staff, travel, and access.","Keep customer and staff communication synchronized.","Update the source job record."]}]'::jsonb,
  26,1,false,1,null,null,now(),now()
)
