insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='servicem8-for-virtual-assistants') and position=2),
  'quotes-options-acceptance-and-follow-up','Quotes, Options, Acceptance, and Follow-Up','ServiceM8 supports quote creation, sending, online acceptance, and quote options. VAs can keep the workflow moving if price, scope, and approval rules are clear.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Support ServiceM8 quote administration","Track acceptance from evidence","Follow up without changing approved commercial terms"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"ServiceM8 supports quote creation, sending, online acceptance, and quote options. VAs can keep the workflow moving if price, scope, and approval rules are clear."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Quotes may use preset labour, parts, bundles, or job-specific items.","Multiple quote options can present alternatives.","Online acceptance can update job state.","Customer questions should be attached to the relevant job/quote context.","Follow-up should stop or change when the quote status changes."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm approved scope and price inputs.","Build or check the draft quote.","Route technical/pricing uncertainty to the responsible person.","Send through the approved channel.","Monitor viewed/questioned/accepted status as the business requires.","Record customer questions.","Create the next follow-up or scheduling action after confirmed acceptance."]},{"type":"callout","title":"Stay inside the role","text":"Do not adjust margins, labour rates, materials, technical scope, warranty, or quote options to win the job unless authorized."},{"type":"callout","title":"Keep this current","text":"ServiceM8 changes over time. Before publishing or reviewing this lesson, verify the current workflow against official ServiceM8 help documentation. The course teaches administrative workflow, not vendor certification."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Sending before approval","Using the wrong quote version","Treating a question as acceptance","Negotiating in chat","Scheduling before the business''s acceptance/deposit rule is met"]},{"type":"scenario","title":"Practice scenario","text":"A customer opens the online quote and asks whether removing one item will reduce the price. Draft the admin response and escalation path."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Quote from approved inputs.","Track acceptance evidence.","Keep commercial decisions with authorized staff.","Update next actions from current status."]}]'::jsonb,
  26,2,false,1,null,null,now(),now()
)
