insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='servicem8-for-virtual-assistants') and position=3),
  'job-completion-forms-photos-and-follow-up','Job Completion, Forms, Photos, and Follow-Up','ServiceM8 can store notes, photos, forms, and job history. A remote VA should use that evidence to determine the administrative next step rather than assuming the job is complete because the scheduled time ended.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Check completion evidence","Track return work and exceptions","Avoid closing jobs prematurely"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"ServiceM8 can store notes, photos, forms, and job history. A remote VA should use that evidence to determine the administrative next step rather than assuming the job is complete because the scheduled time ended."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Completion criteria may include technician status, notes, photos, signatures, forms, or follow-up tasks.","A job may be completed in the field but still need admin work.","A return visit should remain visible.","Customer confirmation may be part of the business''s workflow.","Job history should remain understandable after closeout."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the technician''s latest job record.","Check required completion evidence.","Identify parts, return visits, customer questions, or approval items.","Update the customer using approved information.","Create any follow-up booking/task.","Move to invoicing only when the business''s completion criteria are met."]},{"type":"callout","title":"Stay inside the role","text":"Do not translate sparse technician notes into technical conclusions or compliance statements."},{"type":"callout","title":"Keep this current","text":"ServiceM8 changes over time. Before publishing or reviewing this lesson, verify the current workflow against official ServiceM8 help documentation. The course teaches administrative workflow, not vendor certification."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Closing from calendar end time","Ignoring missing forms","Failing to create return work","Telling the customer the problem is permanently fixed without evidence","Moving to invoice with unresolved scope"]},{"type":"scenario","title":"Practice scenario","text":"The technician uploaded photos but the note says ''needs return with part''. Explain the ServiceM8 status, task, and customer communication you would create."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Use job evidence.","Keep return work visible.","Separate field completion from admin closure.","Do not invent technical conclusions."]}]'::jsonb,
  26,1,false,1,null,null,now(),now()
)
on conflict (module_id,slug) do update set
  title=excluded.title,summary=excluded.summary,content=excluded.content,estimated_minutes=excluded.estimated_minutes,
