insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='servicem8-for-virtual-assistants') and position=3),
  'invoices-payments-statements-and-accounting-handoff','Invoices, Payments, Statements, and Accounting Handoff','ServiceM8 supports invoicing, payments, statements, and accounting integrations. A VA can help cash flow by keeping job and invoice status clean while leaving GST, coding, write-offs, and accounting judgments to authorized finance staff.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Support ServiceM8 billing workflows","Track payments and outstanding invoices","Coordinate accounting integration exceptions"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"ServiceM8 supports invoicing, payments, statements, and accounting integrations. A VA can help cash flow by keeping job and invoice status clean while leaving GST, coding, write-offs, and accounting judgments to authorized finance staff."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Invoices can be generated from job billing information.","Customers may receive invoices or payment links electronically.","Statements can summarize outstanding invoices.","Accounting integrations can sync data with systems such as Xero or MYOB.","Integration does not eliminate reconciliation and exception management."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Confirm the job is ready to invoice.","Check approved billing items and customer details.","Route GST/coding questions to the finance owner.","Issue the invoice if authorized.","Monitor payment status from the system.","Send approved reminder/statement workflows.","Record sync or reconciliation exceptions for the bookkeeper/accountant."]},{"type":"callout","title":"Stay inside the role","text":"Do not change GST treatment, write off debt, create unauthorized credits, or force accounting matches to make systems agree."},{"type":"callout","title":"Keep this current","text":"ServiceM8 changes over time. Before publishing or reviewing this lesson, verify the current workflow against official ServiceM8 help documentation. The course teaches administrative workflow, not vendor certification."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Invoicing unfinished work","Chasing a paid invoice","Assuming integration means everything reconciled correctly","Changing tax settings without approval","Closing outstanding-payment exceptions"]},{"type":"scenario","title":"Practice scenario","text":"ServiceM8 shows an invoice unpaid, but the accounting system appears to show a matching bank receipt. Explain the checks and finance handoff instead of marking it paid yourself."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Align job and invoice status.","Use evidence for payment.","Treat integrations as workflows, not magic.","Escalate accounting exceptions."]}]'::jsonb,
  26,2,false,1,null,null,now(),now()
)
