insert into public.training_modules (course_id,title,summary,position)
values ((select id from public.training_courses where slug='servicem8-for-virtual-assistants'),'Automation, QA, and Simulation','Use software efficiency without losing judgment.',4)
on conflict (course_id,position) do update set title=excluded.title,summary=excluded.summary,updated_at=now();

insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='servicem8-for-virtual-assistants') and position=4),
  'automation-reminders-and-servicem8-workflow-qa','Automation, Reminders, and ServiceM8 Workflow QA','ServiceM8 supports automation and reminders. Automation is valuable only when records, templates, timing, and conditions are correct. A bad automated workflow can repeat mistakes at scale.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Use automation carefully","Check whether automated messages still fit current context","Build a recurring QA routine"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"ServiceM8 supports automation and reminders. Automation is valuable only when records, templates, timing, and conditions are correct. A bad automated workflow can repeat mistakes at scale."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Automations depend on triggers and record status.","Booking confirmations, quote follow-up, payment reminders, and customer communication may be automated.","Templates should use approved wording.","Opt-outs, complaints, changed appointments, and unusual cases may require automation to stop.","QA should sample actual customer-facing outputs."]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Document the automation trigger and intended outcome.","Check the template and variables.","Test on a safe sample or approved test process.","Confirm exclusions and stop conditions.","Monitor exceptions after launch.","Periodically review whether the automation still matches the business process and software behavior."]},{"type":"callout","title":"Stay inside the role","text":"Do not enable customer-facing automation merely because the feature exists. The business must approve messaging, cadence, commercial rules, and exceptions."},{"type":"callout","title":"Keep this current","text":"ServiceM8 changes over time. Before publishing or reviewing this lesson, verify the current workflow against official ServiceM8 help documentation. The course teaches administrative workflow, not vendor certification."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Turning on reminders without checking templates","Automating quote follow-up after acceptance","Sending payment reminders after manual payment","Using AI-generated customer text without review","Never auditing automations after setup"]},{"type":"scenario","title":"Practice scenario","text":"A payment reminder automation is sending to customers whose bank-transfer payments take a day to reconcile. Describe how you would investigate and what decision belongs to the business/finance owner."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Automate defined processes.","Test triggers and exclusions.","Review customer-facing outputs.","Keep humans in exception paths."]}]'::jsonb,
  26,1,false,1,null,null,now(),now()
)
