insert into public.training_lessons (
  module_id,slug,title,summary,content,estimated_minutes,position,is_published,content_version,reviewed_by,last_reviewed_at,created_at,updated_at
) values (
  (select id from public.training_modules where course_id=(select id from public.training_courses where slug='servicem8-for-virtual-assistants') and position=4),
  'servicem8-composite-va-simulation','ServiceM8 Composite VA Simulation','This simulation tests whether you understand ServiceM8 as an operational system rather than a set of screens.','[{"type":"heading","text":"What you''ll learn"},{"type":"list","items":["Use ServiceM8 concepts across a complete job day","Coordinate scheduling, quotes, completion, and invoicing","Show clean escalation and record-keeping"]},{"type":"heading","text":"Why this matters"},{"type":"paragraph","text":"This simulation tests whether you understand ServiceM8 as an operational system rather than a set of screens."},{"type":"heading","text":"Core ideas"},{"type":"list","items":["Client records","Job cards","Dispatch","Quotes","Field evidence","Invoices","Automation exceptions"]},{"type":"heading","text":"A practical workflow"},{"type":"steps","items":["Review the fictional ServiceM8 queue.","Create or correct client/job records.","Resolve routine scheduling.","Prepare quote follow-up.","Process a technician completion exception.","Prepare invoice/payment handoff.","Identify one automation issue.","Produce a clean daily handoff."]},{"type":"callout","title":"Stay inside the role","text":"Do not make technical, pricing, tax, payment-write-off, or safety decisions just because ServiceM8 exposes the related controls."},{"type":"callout","title":"Keep this current","text":"ServiceM8 changes over time. Before publishing or reviewing this lesson, verify the current workflow against official ServiceM8 help documentation. The course teaches administrative workflow, not vendor certification."},{"type":"heading","text":"Common mistakes"},{"type":"list","items":["Using software status instead of real-world evidence","Ignoring duplicate client records","Treating smart suggestions as authority","Sending stale automated messages","Forcing finance records to match"]},{"type":"scenario","title":"Practice scenario","text":"A fictional electrical-services company has a duplicate client, an urgent unscheduled job, a quote question, a technician return visit, an invoice-payment mismatch, and an automation sending the wrong reminder. Work through the system changes, messages, escalations, and final handoff."},{"type":"heading","text":"Before you move on"},{"type":"list","items":["Keep ServiceM8 aligned with reality.","Use permissions responsibly.","Preserve job history.","Escalate technical and financial judgment."]}]'::jsonb,
  26,2,false,1,null,null,now(),now()
)
